  category: "Tin dự án",
  categoryEn: "Projects",
  image: "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEg9NIXEkztkGBsZ_wrKaPGcmd2aPS4Msk_3q8S5K6xGIwbwCJnOguxAMmqbpgbf6uo8B3CheWXIEh19Qq6IobaSirCP4Jc60fA3PJMwlxDFIO8xb8Q3AKEGu4k-jZ4rHHDQnSVockaexPEmGmO6yfUbsGdm0BwPvN_5_k-HtQGmoz8suVGN9qNpFFACfYV8/s800/cua-nhom-co-cau-ea60i.webp",
  imageAlt: "Cửa Nhôm Cầu Cách Nhiệt - Lựa Chọn Hàng Đầu Cho Công Trình Xanh Bền Vững",
